quality_block['body']=quality_block['body'].replace('18,517',f"{quality['inside_records']:,}").replace('30,189',f"{quality['downloaded_records']:,}").replace('**49**',f"**{quality['missing_fields_inside'].get('number_of_persons_killed',0)}**")
